def snake_game(width, height, food, moves):
    from collections import deque
    body = deque([(0, 0)])
    occ = {(0, 0)}
    score = 0
    out = []
    d = {'U': (-1, 0), 'D': (1, 0), 'L': (0, -1), 'R': (0, 1)}
    for m in moves:
        dr, dc = d[m]
        r, c = body[0][0] + dr, body[0][1] + dc
        if not (0 <= r < height and 0 <= c < width):
            out.append(-1)
            break
        eat = score < len(food) and [r, c] == food[score]
        if not eat:
            tail = body.pop()
            occ.discard(tail)
        if (r, c) in occ:
            out.append(-1)
            break
        body.appendleft((r, c))
        occ.add((r, c))
        if eat:
            score += 1
        out.append(score)
    return out
